import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Lumberjacking","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/lumberjacking.md","filePath":"guide/professions/lumberjacking.md"}'),o={name:"guide/professions/lumberjacking.md"};function n(s,e,l,d,c,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="lumberjacking" tabindex="-1">Lumberjacking <a class="header-anchor" href="#lumberjacking" aria-label="Permalink to &quot;Lumberjacking&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/lumberjacking.html">full design specification</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Lumberjacking should reward forestry knowledge and timber selection, not just striking any tree for logs. Species, maturity, health and approximate timber quality can guide where and how you harvest.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Felled trees could occupy several tiles and temporarily alter routes or chokepoints. Controlled felling may have battlefield or siege uses; improvised bridges are only a possible later application. World protections, hazards and recovery must be settled before these become playable rules.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>The Forester’s Journal records species, tree condition and regional ecology. Quick felling, controlled felling and selective cutting are candidate approaches. Selection should save time, reduce tool wear or recover more useful timber, giving players a reason not to clear-cut indiscriminately.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progression and related crafts <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Permalink to &quot;Progression and related crafts&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/professions/overview.html">Shared learning and production principles</a> apply where relevant. Better knowledge and skill should improve material choices and yield. <a href="/Syrolands-Public/guide/professions/carpentry.html">Carpentry</a> uses the timber, while Camping and <a href="/Syrolands-Public/guide/professions/cooking.html">Cooking</a> connect to fuel. Exact regrowth and overharvest behavior remain open.</p><p><a href="/Syrolands-Public/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/game-design/professions/lumberjacking.html">Full design specification</a></p>',11)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
